GWH_st.name='GWH'; 
GWH_st.lat=26.18;
GWH_st.lon=91.75;
GWH_st.alt=0000;
GWH_st.env='Con';
GWH_st.footp='U';
%%
% data imported via the import tool from matlab

GWH_rd_h.Properties.DimensionNames{1}='Time';
GWH_rd_h.Properties.VariableNames{2}='Ba1_A';
GWH_rd_h.Properties.VariableNames{3}='Ba2_A';
GWH_rd_h.Properties.VariableNames{4}='Ba3_A';
GWH_rd_h.Properties.VariableNames{5}='Ba4_A';
GWH_rd_h.Properties.VariableNames{6}='Ba5_A';
GWH_rd_h.Properties.VariableNames{7}='Ba6_A';
GWH_rd_h.Properties.VariableNames{8}='Ba7_A';
names_rd=fieldnames(GWH_rd_h);
%%
GWH_rd=retime(GWH_rd_h,'daily',@nanmedian);
%%
datevec(GWH_rd.Time(1)) % begin in 2016,  %[output:83d97046]
datevec(GWH_rd.Time(end)) % end in 2020  %[output:182b082e]
plotFigControl(GWH_rd,GWH_st.name); %--> absorption is presently too short %[output:65a464fe]
%%
lambdaAE7=[370 470 520 590 660 880 950];
%compute abs exp
Ca3=startsWith(names_rd,{'Ba'}) & contains(names_rd,{'_A'});
names_abs=names_rd(Ca3);
GWH_cal=compute_exp_D(GWH_rd,names_abs,lambdaAE7); %[output:1c057377] %[output:6e78cc21] %[output:74e1596b] %[output:5aabf9dc] %[output:9dc5a947] %[output:35d5a9ba] %[output:9f2c9789] %[output:37fdadff] %[output:8c9c32df] %[output:1d760571] %[output:7dca1fb7] %[output:29f70474] %[output:5527b485] %[output:9e856801]
plotFigControl_cal(GWH_cal,GWH_st.name); %[output:36de917d] %[output:34010cec] %[output:6f67b231]
%%
%HOMOGENEITY

break_GWH_abs_BP=change_point_analysis_Def(GWH_rd,names_abs,0.05,'GWH','Absorption'); %[output:8e145d6b] %[output:55af3446] %[output:48bdb8d8] %[output:3c4a31f7] %[output:93fcc764] %[output:0ecc8496]
T_GWH_abs_BP=make_table_breakpoints_def(break_GWH_abs_BP);

names_expA={'expA_bgAE','expA_brAE','expA_grAE','expA_fit'} %[output:843e1980]
break_GWH_expA_BP=change_point_analysis_Def(GWH_cal,names_expA,0.05,'GWH','Absorption exponent'); %[output:0f802762] %[output:229366c4] %[output:825cc7e0] %[output:7915c7c3]
T_GWH_expA_BP=make_table_breakpoints_def(break_GWH_expA_BP);


